// Webhook body is either an unstructured order ({ from, subject, text }) such as a forwarded
// email or pasted PDF text, or a structured order ({ source, order }) from a portal or ERP.
return $input.all().map((item, i) => {
  const body = item.json.body ?? {};
  return {
    json: {
      intake_id: `${$execution.id}-wh-${i}`,
      source: body.source || 'webhook',
      received_at: new Date().toISOString(),
      sender_email: body.from ?? null,
      subject: body.subject ?? null,
      raw_text: body.text ?? null,
      order: body.order ?? null,
      extraction: body.order ? { method: 'structured', confidence: 1, missing_fields: [] } : null,
    },
  };
});

// Input items come from "Extract PDF Attachment", which errors (and passes { error }) when the
// email has no PDF, so the email itself is read from the trigger.
return $input.all().map((item, i) => {
  const email = $('Email: Orders Inbox').itemMatching(i).json;
  const pdfText = item.json.error ? '' : item.json.text ?? '';
  const body = email.text || String(email.html ?? '').replace(/<[^>]+>/g, ' ');

  return {
    json: {
      intake_id: `${$execution.id}-mail-${i}`,
      source: 'email',
      received_at: email.date ? new Date(email.date).toISOString() : new Date().toISOString(),
      sender_email: email.from?.value?.[0]?.address ?? null,
      subject: email.subject ?? null,
      raw_text: [body, pdfText && `--- PDF attachment ---\n${pdfText}`].filter(Boolean).join('\n\n'),
      order: null,
      extraction: null,
    },
  };
});

// Shopify orders/create payload. Pickup is left empty so "Validate & Normalize Order" uses the
// default warehouse from the config.
return $input.all().map((item, i) => {
  const o = item.json;
  const ship = o.shipping_address ?? {};

  return {
    json: {
      intake_id: `${$execution.id}-shop-${i}`,
      source: 'shopify',
      received_at: o.created_at ?? new Date().toISOString(),
      sender_email: o.email ?? null,
      subject: `Shopify order ${o.name ?? o.id}`,
      raw_text: null,
      order: {
        customer: {
          company: ship.company ?? null,
          contact_name: ship.name ?? null,
          email: o.email ?? o.customer?.email ?? null,
          phone: ship.phone ?? o.phone ?? o.customer?.phone ?? null,
        },
        reference_number: o.name ?? String(o.id),
        service_level: /same.?day/i.test(o.shipping_lines?.[0]?.title ?? '') ? 'same_day' : 'scheduled',
        pickup: null,
        dropoff: {
          name: ship.company || ship.name || null,
          street: [ship.address1, ship.address2].filter(Boolean).join(' ') || null,
          city: ship.city ?? null,
          state: ship.province_code ?? null,
          zip: ship.zip ?? null,
          window_start: null,
          window_end: null,
          instructions: o.note ?? null,
        },
        items: (o.line_items ?? []).map((li) => ({
          description: li.title,
          quantity: li.quantity ?? 1,
          unit: 'box',
          weight_lbs: li.grams ? Math.round(((li.grams * (li.quantity ?? 1)) / 453.6) * 10) / 10 : null,
        })),
        vehicle_type: null,
        special_instructions: o.note ?? null,
      },
      extraction: { method: 'structured', confidence: 1, missing_fields: [] },
    },
  };
});

// One item per CSV row. Column names match samples/orders.csv.
const fileName = $('Drive: New CSV in Folder').first().json.name ?? 'upload.csv';

return $input.all().map((item, i) => {
  const r = item.json;
  const stop = (prefix) => ({
    name: r[`${prefix}_name`] || null,
    street: r[`${prefix}_street`] || null,
    city: r[`${prefix}_city`] || null,
    state: r[`${prefix}_state`] || null,
    zip: r[`${prefix}_zip`] || null,
    window_start: r[`${prefix}_window_start`] || null,
    window_end: r[`${prefix}_window_end`] || null,
    instructions: r[`${prefix}_instructions`] || null,
  });

  return {
    json: {
      intake_id: `${$execution.id}-csv-${i}`,
      source: 'csv',
      received_at: new Date().toISOString(),
      sender_email: r.contact_email || null,
      subject: `${fileName} row ${i + 2}`,
      raw_text: null,
      order: {
        customer: {
          company: r.customer_company || null,
          contact_name: r.contact_name || null,
          email: r.contact_email || null,
          phone: r.contact_phone || null,
        },
        reference_number: r.reference_number || null,
        service_level: r.service_level || 'scheduled',
        pickup: stop('pickup'),
        dropoff: stop('dropoff'),
        items: [{
          description: r.items_description || 'Freight',
          quantity: parseInt(r.quantity, 10) || null,
          unit: r.unit || 'other',
          weight_lbs: parseFloat(r.weight_lbs) || null,
        }],
        vehicle_type: r.vehicle_type || null,
        special_instructions: r.notes || null,
      },
      extraction: { method: 'structured', confidence: 1, missing_fields: [] },
    },
  };
});

