const cfg = $('Load Config').first().json.config;
const ORDER_SCHEMA = {
  "type": "object",
  "additionalProperties": false,
  "required": [
    "customer",
    "reference_number",
    "service_level",
    "pickup",
    "dropoff",
    "items",
    "vehicle_type",
    "special_instructions",
    "confidence",
    "missing_fields"
  ],
  "properties": {
    "customer": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "company",
        "contact_name",
        "email",
        "phone"
      ],
      "properties": {
        "company": {
          "type": [
            "string",
            "null"
          ]
        },
        "contact_name": {
          "type": [
            "string",
            "null"
          ]
        },
        "email": {
          "type": [
            "string",
            "null"
          ]
        },
        "phone": {
          "type": [
            "string",
            "null"
          ]
        }
      }
    },
    "reference_number": {
      "type": [
        "string",
        "null"
      ],
      "description": "Customer PO, order or reference number."
    },
    "service_level": {
      "type": "string",
      "enum": [
        "same_day",
        "scheduled",
        "recurring"
      ]
    },
    "pickup": {
      "$ref": "#/$defs/stop"
    },
    "dropoff": {
      "$ref": "#/$defs/stop"
    },
    "items": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "description",
          "quantity",
          "unit",
          "weight_lbs"
        ],
        "properties": {
          "description": {
            "type": "string"
          },
          "quantity": {
            "type": [
              "integer",
              "null"
            ]
          },
          "unit": {
            "type": "string",
            "enum": [
              "pallet",
              "box",
              "piece",
              "other"
            ]
          },
          "weight_lbs": {
            "type": [
              "number",
              "null"
            ]
          }
        }
      }
    },
    "vehicle_type": {
      "type": [
        "string",
        "null"
      ],
      "description": "Only if the customer asked for a specific vehicle."
    },
    "special_instructions": {
      "type": [
        "string",
        "null"
      ]
    },
    "confidence": {
      "type": "number",
      "description": "0-1. How sure you are that every extracted field is correct and complete."
    },
    "missing_fields": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Dotted paths of required fields that were not in the text, e.g. pickup.zip."
    }
  },
  "$defs": {
    "stop": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "street",
        "city",
        "state",
        "zip",
        "window_start",
        "window_end",
        "instructions"
      ],
      "properties": {
        "name": {
          "type": [
            "string",
            "null"
          ]
        },
        "street": {
          "type": [
            "string",
            "null"
          ]
        },
        "city": {
          "type": [
            "string",
            "null"
          ]
        },
        "state": {
          "type": [
            "string",
            "null"
          ],
          "description": "2-letter US state code."
        },
        "zip": {
          "type": [
            "string",
            "null"
          ]
        },
        "window_start": {
          "type": [
            "string",
            "null"
          ]
        },
        "window_end": {
          "type": [
            "string",
            "null"
          ]
        },
        "instructions": {
          "type": [
            "string",
            "null"
          ]
        }
      }
    }
  }
};

const system = [
  'You extract B2B delivery orders for a logistics company and return JSON matching the schema.',
  'Rules:',
  '- Use only information in the message. Never invent addresses, dates, phone numbers or references. Use null when a value is missing and list its path in missing_fields.',
  '- Resolve relative dates ("tomorrow", "Monday") from the received timestamp and timezone.',
  '- Times are local, formatted YYYY-MM-DDTHH:MM. A single "deliver by" time is dropoff.window_end.',
  '- state is the 2-letter US code and zip is 5 digits.',
  '- customer is the company placing the order. Use the sender email if no other contact email is given.',
  '- service_level is same_day for today/ASAP/urgent, recurring if it repeats, otherwise scheduled.',
  '- confidence is 0.95 or higher only when both full addresses, the pickup time and the item quantities are stated explicitly.',
].join('\n');

const user = [
  `Received: ${$json.received_at} (timezone ${cfg.timezone})`,
  `From: ${$json.sender_email ?? 'unknown'}`,
  `Subject: ${$json.subject ?? ''}`,
  '',
  $json.raw_text ?? '',
].join('\n');

return {
  json: {
    ...$json,
    ai_request: {
      model: cfg.openai_model,
      temperature: 0,
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'logistics_order', strict: true, schema: ORDER_SCHEMA },
      },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
};

const { ai_request, ...envelope } = $('Build AI Request').item.json;
const content = $json.choices?.[0]?.message?.content;

let extracted;
try {
  extracted = JSON.parse(content);
} catch (e) {
  throw new Error(`AI returned invalid JSON for intake ${envelope.intake_id}: ${String(content).slice(0, 200)}`);
}

const { confidence = 0, missing_fields = [], ...order } = extracted;

return {
  json: {
    ...envelope,
    order,
    extraction: { method: 'ai', model: $json.model, confidence, missing_fields },
  },
};

const cfg = $('Load Config').first().json.config;

const clean = (v) => (typeof v === 'string' ? v.trim().replace(/\s+/g, ' ') || null : v ?? null);

const phone = (p) => {
  const d = String(p ?? '').replace(/\D/g, '');
  if (d.length === 10) return `+1${d}`;
  if (d.length === 11 && d.startsWith('1')) return `+${d}`;
  return null;
};

const time = (t) => {
  const m = String(t ?? '').match(/^(\d{4}-\d{2}-\d{2})[T ](\d{1,2}):(\d{2})/);
  return m ? `${m[1]}T${m[2].padStart(2, '0')}:${m[3]}` : null;
};

const stop = (s = {}) => ({
  name: clean(s.name),
  street: clean(s.street),
  city: clean(s.city),
  state: clean(s.state)?.toUpperCase().slice(0, 2) ?? null,
  zip: String(s.zip ?? '').match(/\d{5}/)?.[0] ?? null,
  window_start: time(s.window_start),
  window_end: time(s.window_end),
  instructions: clean(s.instructions),
});

const today = new Date().toISOString().slice(0, 10);
const tomorrow = new Date(Date.now() + 864e5).toISOString().slice(0, 10);

return $input.all().map(({ json: input }) => {
  const src = input.order ?? {};
  const issues = [];

  // Store orders have no pickup: they ship from the default warehouse during opening hours.
  const pickup = src.pickup
    ? stop(src.pickup)
    : stop({ ...cfg.default_pickup, window_start: `${tomorrow}T09:00`, window_end: `${tomorrow}T17:00` });
  const dropoff = stop(src.dropoff ?? {});

  const customer = {
    company: clean(src.customer?.company),
    contact_name: clean(src.customer?.contact_name),
    email: clean(src.customer?.email ?? input.sender_email)?.toLowerCase() ?? null,
    phone: phone(src.customer?.phone),
  };

  const items = (Array.isArray(src.items) ? src.items : []).map((it) => ({
    description: clean(it.description) ?? 'Freight',
    quantity: parseInt(it.quantity, 10) || null,
    unit: ['pallet', 'box', 'piece', 'other'].includes(it.unit) ? it.unit : 'other',
    weight_lbs: Number(it.weight_lbs) || null,
  }));

  const order = {
    customer,
    reference_number: clean(src.reference_number),
    service_level: ['same_day', 'scheduled', 'recurring'].includes(src.service_level) ? src.service_level : 'scheduled',
    pickup,
    dropoff,
    items,
    vehicle_type: clean(src.vehicle_type),
    special_instructions: clean(src.special_instructions),
  };

  for (const [side, s] of [['pickup', pickup], ['dropoff', dropoff]]) {
    const missing = ['street', 'city', 'state', 'zip'].filter((f) => !s[f]);
    if (missing.length) issues.push(`Missing ${side} ${missing.join(', ')}`);
  }
  if (!pickup.window_start) issues.push('Missing pickup date/time');
  else if (pickup.window_start.slice(0, 10) < today) issues.push(`Pickup date ${pickup.window_start.slice(0, 10)} is in the past`);
  if (pickup.window_start && pickup.window_end && pickup.window_end < pickup.window_start) issues.push('Pickup window ends before it starts');
  if (pickup.window_start && dropoff.window_end && dropoff.window_end < pickup.window_start) issues.push('Delivery deadline is before pickup');
  if (!items.length || items.every((i) => !i.quantity)) issues.push('Missing item quantity');
  if (!customer.email) issues.push('No customer email for the confirmation');

  // Same customer + reference + route + day = same order, even if it arrives twice by different channels.
  // Without both streets and a date that key would collide across unrelated orders, so fall back to the content.
  const hasRoute = pickup.street && dropoff.street && pickup.window_start;
  const key_source = (hasRoute
    ? [
        customer.email ?? customer.company ?? '',
        order.reference_number ?? '',
        pickup.street, pickup.zip ?? '',
        dropoff.street, dropoff.zip ?? '',
        pickup.window_start.slice(0, 10),
      ]
    : ['content', input.sender_email ?? '', (input.raw_text ?? JSON.stringify(src)).replace(/\s+/g, ' ')]
  ).join('|').toLowerCase();

  return {
    json: {
      intake_id: input.intake_id,
      source: input.source,
      received_at: input.received_at,
      sender_email: input.sender_email,
      subject: input.subject,
      extraction: input.extraction ?? { method: 'unknown', confidence: 0, missing_fields: [] },
      order,
      issues,
      key_source,
    },
  };
});

const ctx = JSON.parse(JSON.stringify($('Idempotency Key').item.json));

const PRECISE = ['ROOFTOP', 'RANGE_INTERPOLATED'];
const readGeocode = (res) => {
  const r = res?.results?.[0];
  if (res?.status !== 'OK' || !r) return { verified: false, status: res?.status ?? 'ERROR' };
  return {
    verified: PRECISE.includes(r.geometry.location_type) && !r.partial_match,
    status: res.status,
    location_type: r.geometry.location_type,
    formatted_address: r.formatted_address,
    lat: r.geometry.location.lat,
    lng: r.geometry.location.lng,
    place_id: r.place_id,
  };
};

ctx.geo = {
  pickup: readGeocode($('Maps: Geocode Pickup').item.json),
  dropoff: readGeocode($json),
};

for (const side of ['pickup', 'dropoff']) {
  const g = ctx.geo[side];
  if (!g.verified) ctx.issues.push(`Google Maps could not verify the ${side} address (${g.location_type ?? g.status})`);
}

ctx.quote_request = {
  pickup: { lat: ctx.geo.pickup.lat ?? null, lng: ctx.geo.pickup.lng ?? null },
  dropoff: { lat: ctx.geo.dropoff.lat ?? null, lng: ctx.geo.dropoff.lng ?? null },
  items: ctx.order.items,
  service_level: ctx.order.service_level,
  vehicle_type: ctx.order.vehicle_type,
};

return { json: ctx };

const ctx = $('Apply Address Validation').item.json;
const existing = $json.data[0];

return {
  json: {
    status: 'duplicate',
    message: `Already in the TMS as ${existing.id} (${existing.status}). Nothing new was created.`,
    intake_id: ctx.intake_id,
    shipment_id: existing.id,
    shipment_status: existing.status,
    idempotency_key: ctx.idempotency_key,
  },
};

// Input is the TMS quote, or { error } when the TMS could not price the order.
const cfg = $('Load Config').first().json.config;
const ctx = $('Apply Address Validation').item.json;
const quote = typeof $json.total === 'number' ? $json : null;

const reasons = [];
if (ctx.extraction.confidence < cfg.min_confidence) {
  reasons.push(`AI confidence ${ctx.extraction.confidence} is below ${cfg.min_confidence}`);
}
reasons.push(...ctx.issues);
if (!quote) {
  const err = $json.error;
  const raw = String((typeof err === 'string' ? err : err?.message ?? err?.description) ?? '');
  const detail = raw.match(/"error\\?":\s*\\?"([^"\\]+)/)?.[1] ?? raw.replace(/^\d{3} - /, '');
  reasons.push(`TMS could not quote this order${detail ? `: ${detail}` : ''}`);
} else if (quote.total > cfg.max_auto_price) {
  reasons.push(`Quote $${quote.total} is above the $${cfg.max_auto_price} auto-book limit`);
}

const withGeo = (stop, g) => ({
  ...stop,
  formatted_address: g.formatted_address ?? null,
  lat: g.lat ?? null,
  lng: g.lng ?? null,
});

const tms_payload = {
  reference_number: ctx.order.reference_number,
  source: ctx.source,
  external_ref: ctx.intake_id,
  customer: ctx.order.customer,
  service_level: ctx.order.service_level,
  pickup: withGeo(ctx.order.pickup, ctx.geo.pickup),
  dropoff: withGeo(ctx.order.dropoff, ctx.geo.dropoff),
  items: ctx.order.items,
  vehicle_type: ctx.order.vehicle_type ?? quote?.vehicle_type ?? null,
  special_instructions: ctx.order.special_instructions,
  quote_id: quote?.quote_id ?? null,
  price: quote?.total ?? null,
  ai: { method: ctx.extraction.method, model: ctx.extraction.model ?? null, confidence: ctx.extraction.confidence },
};

return {
  json: {
    ...ctx,
    quote,
    needs_review: reasons.length > 0,
    review_reasons: reasons,
    review_expires_at: Math.floor(Date.now() / 1000) + 24 * 3600,
    tms_payload,
  },
};

// Input is a dispatched TMS shipment. Shared by the intake and review workflows.
const s = $json;
const at = (t) => (t ? String(t).replace('T', ' ') : 'TBD');
const place = (stop = {}) => stop.formatted_address || [stop.street, stop.city, stop.state, stop.zip].filter(Boolean).join(', ');
const ref = s.reference_number ? ` (your ref ${s.reference_number})` : '';

const body = [
  `Hi ${s.customer?.contact_name ?? 'there'},`,
  '',
  `Your delivery is booked${ref}.`,
  '',
  `Shipment:      ${s.id}`,
  `Pickup:        ${place(s.pickup)}`,
  `Pickup ETA:    ${at(s.route?.pickup_eta)}`,
  `Deliver to:    ${place(s.dropoff)}`,
  `Delivery ETA:  ${at(s.route?.eta)}`,
  `Vehicle:       ${s.vehicle_type ?? 'Assigned by dispatch'}`,
  `Driver:        ${s.route?.driver?.name ?? 'Assigned shortly'}`,
  s.price != null ? `Price:         $${s.price.toFixed(2)}` : null,
  '',
  s.route?.tracking_url ? `Track it live: ${s.route.tracking_url}` : null,
  '',
  'Reply to this email if anything needs to change.',
  '',
  'Dispatch team',
].filter((line) => line !== null);

return {
  json: {
    shipment_id: s.id,
    email: {
      personalizations: [{ to: [{ email: s.customer?.email }] }],
      subject: `Booked: ${s.id}${ref}`,
      content: [{ type: 'text/plain', value: body.join('\n') }],
    },
  },
};

const ctx = $('Decide: Auto-book or Review').item.json;
const shipment = $('TMS: Dispatch to Route').item.json;

return {
  json: {
    status: 'booked',
    message: `Booked and dispatched as ${shipment.id}. Confirmation emailed to ${shipment.customer?.email}.`,
    intake_id: ctx.intake_id,
    shipment_id: shipment.id,
    route_id: shipment.route?.id ?? null,
    driver: shipment.route?.driver?.name ?? null,
    pickup_eta: shipment.route?.pickup_eta ?? null,
    delivery_eta: shipment.route?.eta ?? null,
    price: ctx.quote?.total ?? null,
    extraction: ctx.extraction,
  },
};

// Input is the draft shipment plus review_sig from "Sign Review Link".
const cfg = $('Load Config').first().json.config;
const ctx = $('Decide: Auto-book or Review').item.json;
const draft = $json;
const order = ctx.order;

const link = (action) =>
  `${cfg.public_url}/webhook/order-review?shipment_id=${encodeURIComponent(draft.id)}` +
  `&action=${action}&exp=${ctx.review_expires_at}&sig=${draft.review_sig}`;

const place = (s) => [s.street, s.city, s.state, s.zip].filter(Boolean).join(', ') || '_missing_';
const items = order.items.map((i) => `${i.quantity ?? '?'} ${i.unit} - ${i.description}`).join('\n') || '_none_';

const slack = {
  text: `Order needs review: ${draft.id}`,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: `Order needs review: ${draft.id}` } },
    { type: 'section', text: { type: 'mrkdwn', text: `*Why it was held*\n${ctx.review_reasons.map((r) => `- ${r}`).join('\n')}` } },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Customer*\n${order.customer.company ?? order.customer.email ?? '_unknown_'}` },
        { type: 'mrkdwn', text: `*Reference*\n${order.reference_number ?? '_none_'}` },
        { type: 'mrkdwn', text: `*Pickup*\n${place(order.pickup)}\n${order.pickup.window_start ?? '_no time_'}` },
        { type: 'mrkdwn', text: `*Dropoff*\n${place(order.dropoff)}\n${order.dropoff.window_end ? `by ${order.dropoff.window_end}` : ''}` },
        { type: 'mrkdwn', text: `*Items*\n${items}` },
